lemma mem_indepSetFinsetAll_and_subset_of_mem_induce {S : Set V} {I : Set S}
    (hI : I ∈ ℐ(induce S G)) :
    Subtype.val '' I ∈ ℐ(G) ∧ Subtype.val '' I ⊆ S

lemma subset_compl_closedNeighborSet_iff_insert_mem_indepSetFinsetAll {v : V} {I : Set V}
    (hI : I ∈ ℐ(G)) :
    I ⊆ (G.closedNeighborSet v)ᶜ ↔ v ∉ I ∧ insert v I ∈ ℐ(G)

lemma _root_.ConvexOn.map_expect_le {α : Type*} {t : Finset α} (ht : t.Nonempty) {s : Set ℝ}
    {f : ℝ → ℝ} (p : α → ℝ) (hmem : ∀ i ∈ t, p i ∈ s) (hf : ConvexOn ℝ s f) :
    f (𝔼 i ∈ t, p i) ≤ 𝔼 i ∈ t, f (p i)

theorem triangle_free_independence_bound {V : Type} [Fintype V] {G : SimpleGraph V}
    (hT : G.CliqueFree 3) : G.indepNum ≥
        (Fintype.card V : ℝ) *
        (fun x ↦
          if x = 1 then 1/2
          else          (x * Real.log x - x + 1) / (x - 1)^2) (G.averageDegree)

theorem triangle_free_independence_count_bound {V : Type} [Fintype V] {G : SimpleGraph V}
    (hT : G.CliqueFree 3) : #({s | G.IsIndepSet s} : Finset (Set V)) ≥
        Real.exp (
          (Fintype.card V : ℝ) *
          (fun x ↦
            if x = 2 then Real.exp (-W 2)
            else          ((1 / 2) * (W x)^2 + W x - ((1 / 2) * (W 2)^2 + W 2)) / (x - 2))
              (G.averageDegree)
           )

